templates.template:
.graphList
{
	.m-listPlain();
	display: flex;
	flex-wrap: wrap;
	justify-content: center;

	> li
	{
		width: 50%;
	}

	@media (max-width: @xf-responsiveMedium)
	{
		display: block;

		> li
		{
			width: 100%;
		}
	}
}
.p-body-sidebarCol 
{
	display:none;	
}
.p-body-sidebar
{
	display:none;
}

.iconicLinks
{
	margin-bottom: @xf-elementSpacer;
}

.iconicLinks-list
{
	.m-listPlain();
	margin-bottom: -@xf-paddingMedium;
	margin-right: -@xf-paddingMedium;
	font-size: 0;

	display: flex;
	flex-flow: row wrap;

	> li
	{
		flex: auto;

		width: 160px;
		max-width: 320px;

		position: relative;
		overflow: hidden;

		margin-right: @xf-paddingMedium;
		margin-bottom: @xf-paddingMedium;
		vertical-align: top;
		text-align: center;
		font-size: @xf-fontSizeNormal;
		.xf-contentBase();
		.xf-blockBorder();
		border-radius: @xf-blockBorderRadius;

		&.iconicLinks-placeholder
		{
			margin-top: 0;
			margin-bottom: 0;
			height: 0;
			border: none;
		}

		> a
		{
			display: block;
			padding: @xf-paddingLarge;
			background: fade(@xf-contentHighlightBg, 0%);
			.m-transition();

			&:hover
			{
				background: @xf-contentHighlightBg;
				text-decoration: none;

				.iconicLinkList-icon
				{
					opacity: 1;
				}
			}
		}
	}
}

.iconicLinks-icon
{
	font-size: 3em;
	opacity: .6;
	.m-transition(opacity);
}

.iconicLinks-title
{
	.m-overflowEllipsis();
}
.faRegList 
{
	font-size:28px;
	color: @xf-textColorAttention;
}
.noteUser
{
	font-weight:700;
}
.noteList {
    list-style: none;
    margin: 0;
    padding: 0;
}

.noteList li {
    list-style: none;
    position: relative;
	display: inline;
}

.noteList li.noteBullet::before {
    content: "\00B7\20"; 
   display: inline-block;
}
.notePriv
{
	margin-right:5px;
}
.noWrap
{
	white-space: nowrap;
}

.listColumns
{
	&.contentTypes
	{
		margin-bottom: 14px;
	}
}

.ct-chart
{
	svg
	{
		-webkit-backface-visibility: hidden;
	}

	.ct-series-a
	{
		.ct-line,
		.ct-point
		{
			stroke: @xf-paletteColor3;
		}
	}

	.ct-series-b
	{
		.ct-line,
		.ct-point
		{
			stroke: @xf-paletteAccent2;
		}
	}

	.ct-series-c
	{
		.ct-line,
		.ct-point
		{
			stroke: @xf-paletteColor5;
		}
	}

	.ct-series-d
	{
		.ct-line,
		.ct-point
		{
			stroke: @xf-paletteAccent3;
		}
	}

	.ct-grid
	{
		stroke: fade(@xf-textColor, 15%);
	}

	.ct-label
	{
		color: @xf-textColor;
		font-size: @xf-fontSizeSmallest;
	}

	.ct-line
	{
		stroke-width: 2px;
	}

	.ct-point
	{
		stroke-width: 8px;
	}

	.ct-label.ct-horizontal.ct-end
	{
		.m-transform(translateX(-50%));
		text-align: center;
		justify-content: center;
	}
}

.ct-chart--small
{
	.ct-point
	{
		opacity: 0;
	}
}

.ct-legend
{
	.m-listPlain();
	text-align: center;
	font-size: @xf-fontSizeSmaller;

	> li
	{
		display: inline-block;
		position: relative;
        padding-left: 16px;
		margin-right: 2em;

		&:last-child
		{
			margin-right: 0;
		}

		i
		{
			content: '';
			position: absolute;
			left: 0;
			top: 3px;
			width: 12px;
			height: 12px;
			border-radius: @xf-borderRadiusSmall;
			background: transparent;
		}
	}
}
